package net.battlespades.session;
import java.util.*;
import java.util.function.Consumer;
import net.battlespades.combat.BlastRuntime;
import net.battlespades.match.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import net.battlespades.player.*;
import net.battlespades.protocol.*;
import net.battlespades.protocol.DropPickup.Position;
import net.battlespades.rules.GameRules;
import org.tomlj.TomlTable;

/** Asymmetric bombs: live carry identity, uninterrupted fuse, disposal, native blast and respawn waves. */
public final class HostedOccupationRuntime extends HostedCarryRuntime {
    private static final class Bomb {final int serial;Integer entity;Vector at;PlayerLife carrier,lastCarrier;int lastTeam=1;boolean armed,intercepted;double explode,pickup;Bomb(int serial,Vector at){this.serial=serial;this.at=at;}}
    public record State(int serial,Integer entity,Vector position,PlayerLife carrier,int lastTeam,boolean armed,boolean intercepted,double explodeAt,double pickupAfter){}
    private final Map<Integer,Bomb> bombs=new LinkedHashMap<>();private final List<Double> pending=new ArrayList<>();private final List<Vector> spawnPoints=new ArrayList<>();private final int maximum;private final double fuse;private final ObjectiveGuard.TrapTimer<Integer> traps=new ObjectiveGuard.TrapTimer<>();private final Set<PlayerLife> inBase=Collections.newSetFromMap(new IdentityHashMap<>());
    private ObjectiveZone target;private int serial=1,cursor;private double nextScore,nextGuard,nextShout;
    public HostedOccupationRuntime(StandardMatchDomain m,ApplicationHost h,CarryMode mode,SpawnGeometry geometry,TomlTable raw,GameRules rules){super(m,h,mode,geometry,raw);maximum=(int)Math.max(1,Math.min(3,CtfMode.Settings.number(raw,"modes.oc.max_active_bombs",rules.number("RULE_MAX_ACTIVE_BOMBS"))));fuse=Math.max(1,CtfMode.Settings.number(raw,"modes.oc.bomb_fuse_time",rules.number("RULE_BOMB_FUSE_TIME")));}
    public List<State> states(){owned();return bombs.values().stream().map(b->new State(b.serial,b.entity,b.at,b.carrier,b.lastTeam,b.armed,b.intercepted,b.explode,b.pickup)).toList();}
    public ObjectiveZone target(){owned();return target;}
    public boolean carrying(PlayerLife p){owned();return bombs.values().stream().anyMatch(b->b.carrier==p);}
    private Bomb carried(PlayerLife p){return bombs.values().stream().filter(b->b.carrier==p).findFirst().orElse(null);}
    private boolean inside(Vector p){return target!=null&&target.contains(p);}
    private boolean footprint(Vector p){return target!=null&&p.x()>=target.x0()&&p.x()<=target.x1()&&p.y()>=target.y0()&&p.y()<=target.y1();}
    public void start(){owned();var metadata=match.metadata();int shift=match.world().sourceZShift();var authored=metadata.occupationBase();if(authored==null){var bases=metadata.spawnLayout().bases().getOrDefault(3,List.of());if(!bases.isEmpty())authored=bases.getFirst();}target=authored==null?ObjectiveZone.around(0,anchor(3),16,12,16):ObjectiveZone.from(0,authored,shift);spawnPoints.clear();for(var p:metadata.occupationBombs().stream().limit(5).toList())spawnPoints.add(new Vector(p.x(),p.y(),p.z()+shift));if(spawnPoints.isEmpty()){var a=anchor(2);var b=anchor(3);for(double f:new double[]{.35,.45,.55})spawnPoints.add(new net.battlespades.entities.PickupWorld(match.world()).drySurfaceAnchor(a.x()+(b.x()-a.x())*f,a.y()+(b.y()-a.y())*f,48));}cursor=0;inBase.clear();nextShout=0;traps.clear();nextGuard=0;broadcast(target.packet(team(3).color(),3));for(int i=0;i<maximum;i++)spawnBomb();for(var p:match.lives().players())startCue(p,packet->personal(p,packet));wave(false);nextScore=match.wall()+5;}
    private void spawnBomb(){var b=new Bomb(serial++,spawnPoints.get(cursor++%spawnPoints.size()));b.entity=entity(14,b.at,"occupation_bomb",0);b.pickup=match.wall();bombs.put(b.serial,b);}
    private void wave(boolean override){teamMessage(2,"TAKE_BOMB_TO_ENEMY_BASE",List.of(),null,override);teamMessage(3,"STOP_BOMB_REACHING_BASE",List.of(),null,override);}
    private void pickup(PlayerLife p,Bomb b){if(!ObjectiveCarry.pickup(p,14,true,b.serial,this::broadcast))return;if(b.entity!=null)remove(b.entity,"occupation_bomb");b.entity=null;observation("bomb_picked_up",p,null,b.serial,b.lastCarrier==null,null,b.at);b.carrier=p;b.lastCarrier=p;b.lastTeam=p.team();if(b.armed&&p.team()==3)b.intercepted=true;guard.endProtection(p);String attack=p.team()==2?"PLAYER_HAS_BOMB_ATTACK":b.intercepted?"PLAYER_HAS_BOMB_KILL":"DEFENDER_HAS_THE_BOMB_ATTACK",defend=p.team()==2?"PLAYER_HAS_BOMB_DEFEND":b.intercepted?"PLAYER_HAS_BOMB_HIDE":"DEFENDER_HAS_THE_BOMB_DEFEND";teamMessage(2,attack,List.of(p.name()),null,false);teamMessage(3,defend,List.of(p.name()),null,false);}
    public boolean drop(PlayerLife p,Position at,Position speed,boolean forced,Integer oldTeam){owned();var b=carried(p);if(b==null)return false;var dropped=nativeDrop(p,at,speed,forced);if(dropped==null&&!forced)return true;b.carrier=null;if(!open())return true;b.lastCarrier=p;b.at=surface(dropped==null?p.position().x():dropped.position().x(),dropped==null?p.position().y():dropped.position().y());sound(22,b.at);observation("bomb_dropped",p,null,b.serial,footprint(b.at),null,b.at);if(!b.armed){b.armed=true;b.explode=match.wall()+fuse;}b.entity=entity(14,b.at,"occupation_bomb_armed",Math.max(.05,b.explode-match.wall()));b.pickup=match.wall()+2.5;return true;}
    private void detonate(Bomb b){PlayerLife thrower=b.carrier;if(thrower!=null){if(current(thrower)){nativeDrop(thrower,position(thrower.position()),new Position(0,0,0),true);b.at=surface(thrower.position().x(),thrower.position().y());}b.carrier=null;}if(b.entity==null)b.entity=entity(14,b.at,"occupation_bomb_exploding",.05);boolean in=footprint(b.at);PlayerLife scorer=current(b.lastCarrier)&&b.lastCarrier.team()==b.lastTeam?b.lastCarrier:null;
        if(in){teamScore(2,3,28);if(scorer!=null&&b.lastTeam==2)award(scorer,50,28);announce("BOMB_SUCCESSFUL",List.of(team(3).name),true);}else {if(scorer!=null&&b.lastTeam==3)award(scorer,25,b.intercepted?37:36);announce("BOMB_FAIL",List.of(team(3).name),true);}
        var witnesses=match.lives().players().stream().filter(p->active(p)&&ObjectiveScores.within(p.position(),b.at,7)&&(thrower==null||match.friendlyFire()||p.team()!=thrower.team())).toList();var blast=new BlastRuntime.Request(b.at,500,20,17,thrower);blast.radius=7;blast.minimum=2;blast.maximum=3;blast.nativeType=19;blast.causerEntity=b.entity;match.entities().blasts().apply(blast);for(var p:witnesses)if(active(p))award(p,50,33);observation("bomb_detonated",b.lastTeam==2?scorer:null,null,b.serial,in,null,b.at);sound(b.at.z()>238?17:18,b.at);remove(b.entity,"occupation_bomb");bombs.remove(b.serial);pending.add(match.wall()+10);if(in)checkScore(2);
    }
    private void recover(){double now=match.monotonic();if(now<nextGuard)return;nextGuard=now+1;for(var b:bombs.values()){boolean idle=b.entity!=null&&b.carrier==null&&!b.armed;if(!traps.due(b.serial,idle&&guard.trapped(b.at,false)!=null,now,guard.entombSeconds()))continue;try{var at=guard.resettle(b.at,false);remove(b.entity,"occupation_bomb");b.at=at;b.entity=entity(14,at,"occupation_bomb",0);}catch(RuntimeException e){match.failure("bomb recovery",e);}}}
    public void tick(){owned();if(!open())return;double now=match.wall();int due=(int)pending.stream().filter(t->t<=now).count();pending.removeIf(t->t<=now);boolean spawned=false;for(int i=0;i<due&&bombs.size()<maximum;i++){spawnBomb();spawned=true;}if(spawned)wave(true);recover();
        for(var p:match.lives().players())if(active(p)&&!carrying(p)){var b=bombs.values().stream().filter(v->v.entity!=null&&v.carrier==null&&now>=v.pickup&&ObjectiveScores.within(p.position(),v.at,3)&&guard.pickupVisible(p,v.at,false,0)).min(Comparator.comparingInt(v->v.serial)).orElse(null);if(b!=null)pickup(p,b);}
        var currentInside=Collections.newSetFromMap(new IdentityHashMap<PlayerLife,Boolean>());for(var b:bombs.values())if(b.carrier!=null&&b.carrier.team()==2&&inside(b.carrier.position()))currentInside.add(b.carrier);boolean entered=currentInside.stream().anyMatch(p->!inBase.contains(p));inBase.clear();inBase.addAll(currentInside);if(entered&&now>=nextShout){nextShout=now+5;teamMessage(2,"BASE_OCCUPIED_ATTACK",List.of(),null,true);teamMessage(3,"BASE_OCCUPIED_DEFEND",List.of(),null,true);}
        for(var b:List.copyOf(bombs.values()))if(b.carrier!=null&&b.carrier.bot()){var p=b.carrier;double dx=Math.max(0,Math.max(target.x0()-p.position().x(),p.position().x()-target.x1())),dy=Math.max(0,Math.max(target.y0()-p.position().y(),p.position().y()-target.y1()));if(p.team()==2&&!b.armed&&inside(p.position())||p.team()==3&&Math.hypot(dx,dy)>=20)retire(p,null);}
        for(var b:List.copyOf(bombs.values()))if(b.armed&&now>=b.explode){detonate(b);if(!open())return;}else if(b.entity!=null&&b.armed){var e=match.entities().registry().get(b.entity);if(e!=null)e.fuse=Math.max(.05,b.explode-now);}
        if(now>=nextScore){long periods=(long)Math.floor((now-nextScore)/5)+1;nextScore+=periods*5;for(var b:bombs.values())if(active(b.carrier))award(b.carrier,periods*50,27);for(var p:match.lives().players())if(active(p)&&p.team()==2&&inside(p.position()))award(p,periods*50,26);}
    }
    public void death(Scoreboard.Player v,Scoreboard.Player k,int type){owned();var b=carried(v.life);if(open()&&ObjectiveScores.eligible(k,v,type)){var kc=bombs.values().stream().map(x->x.carrier).filter(p->p!=null&&p.team()==k.team()).map(p->match.binding().row(p)).toList();var vc=bombs.values().stream().map(x->x.carrier).filter(p->p!=null&&p.team()==v.team()).map(p->match.binding().row(p)).toList();var ground=bombs.values().stream().filter(x->x.entity!=null&&x.carrier==null).toList();if(b==null||b.lastTeam==k.team()){String event=ObjectiveScores.classify(k,v,false,kc,ground.stream().filter(x->x.armed&&x.lastTeam==k.team()).map(x->x.at).toList(),ground.stream().filter(x->!x.armed||x.lastTeam!=k.team()).map(x->x.at).toList(),10,20);scores.killEvent(k,event,Map.of("carrier_defend",100L,"defend",50L,"assault",100L,"distract",100L),Map.of("carrier_defend",30,"defend",31,"assault",32,"distract",29),Optional.empty());}if(ObjectiveScores.distraction(v,k,type,vc,20))award(v.life,100,29);}
        if(open()&&b!=null&&k!=null&&k.life!=v.life&&(k.team()==2||k.team()==3)&&k.team()!=b.lastTeam){teamScore(k.team(),1,34);award(k.life,50,34);if(b.lastTeam==2)observation("bomb_carrier_killed",k.life,v.life,b.serial,false,null,v.life.position());checkScore(k.team());}retire(v.life,null);
    }
    public void startCue(PlayerLife p,Consumer<GamePacket> send){if(p.team()==2||p.team()==3)send.accept(Announcements.localised(p.team()==2?"OCCUPATION_START_ATTACK":"OCCUPATION_START_DEFEND",List.of(),false,false));}
    public void reveal(Consumer<GamePacket> send){owned();if(target!=null)send.accept(target.packet(team(3).color(),3));}
    public void clear(){owned();for(var b:List.copyOf(bombs.values())){if(b.carrier!=null){if(current(b.carrier))nativeDrop(b.carrier,position(b.carrier.position()),new Position(0,0,0),true);else ObjectiveCarry.clear(b.carrier);}if(b.entity!=null)remove(b.entity,"occupation_bomb");}bombs.clear();pending.clear();inBase.clear();traps.clear();}
}
